const raw = $input.first().json;
const p = raw.body || raw;
const isEmpty = !p || Object.keys(p).length === 0;

// Manual test runs have no payload - use a sample message so the workflow is testable end to end
const sample = { userId: 'demo-user', sessionId: 'demo-session', message: 'Hi! I am Priya, a backend engineer. I prefer Go over Java and I am preparing for a conference talk next month.' };
const src = isEmpty ? sample : p;

const ID_RE = /^[A-Za-z0-9_.@-]{1,128}$/;
const userId = String(src.userId || '').trim();
const sessionId = String(src.sessionId || 'default').trim();
const message = typeof src.message === 'string' ? src.message.trim() : '';

let error = null;
if (!ID_RE.test(userId)) error = 'userId is required (letters, numbers, . _ @ - only, max 128 chars)';
else if (!ID_RE.test(sessionId)) error = 'sessionId may only contain letters, numbers, . _ @ - (max 128 chars)';
else if (!message) error = 'message is required';
else if (message.length > 4000) error = 'message is too long (max 4000 characters)';

return [{
  json: {
    inputValid: !error,
    validationError: error,
    requestId: 'req-' + Date.now(),
    userId,
    sessionId,
    sessionKey: 'session:' + userId + ':' + sessionId,
    message,
    startedAt: new Date().toISOString()
  }
}];

const state = $('Set Configuration Parameters').first().json;
const r = $input.first().json;

let history = [];
try {
  const v = r.history;
  history = Array.isArray(v) ? v : (v ? JSON.parse(v) : []);
} catch (e) { history = []; }
history = history.filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string');

// Cheap deterministic hash of the message for the embedding cache key
function djb2(s) { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); }
function sdbm(s) { let h = 0; for (let i = 0; i < s.length; i++) h = (s.charCodeAt(i) + (h << 6) + (h << 16) - h) | 0; return (h >>> 0).toString(36); }
const embeddingCacheKey = 'emb:' + state.embeddingModel + ':' + state.message.length + ':' + djb2(state.message) + sdbm(state.message);

return [{ json: { ...state, history, embeddingCacheKey } }];

const state = $('Parse Session History').first().json;
const r = $input.first().json;

let emb = null;
try {
  const v = r.cachedEmbedding;
  emb = Array.isArray(v) ? v : (v ? JSON.parse(v) : null);
} catch (e) { emb = null; }
const ok = Array.isArray(emb) && emb.length > 0 && emb.every(x => typeof x === 'number');

return [{ json: { ...state, queryEmbedding: ok ? emb : null, embeddingCacheHit: ok } }];

const state = $('Resolve Cached Embedding').first().json;
const r = $input.first().json;
const emb = r.data && r.data[0] && r.data[0].embedding;
const ok = Array.isArray(emb) && emb.length > 0;

return [{ json: { ...state, queryEmbedding: ok ? emb : null, embeddingCacheHit: false } }];

const s = $input.first().json;
const { queryEmbedding, ...rest } = s;

const dim = Number(s.embeddingDimensions) || 1024;
const hasEmb = Array.isArray(queryEmbedding) && queryEmbedding.length === dim;

// Graceful degradation: without a usable embedding, search with a zero vector and 0 candidates
// so the agent still replies (just without long-term recall).
const vec = hasEmb ? queryEmbedding : new Array(dim).fill(0);
const literal = '[' + vec.join(',') + ']';

return [{
  json: {
    ...rest,
    memorySearchDegraded: !hasEmb,
    searchParams: [
      s.userId,
      literal,
      hasEmb ? s.retrievalCandidates : 0,
      s.minSimilarity,
      s.retrievalTopK,
      s.recencyDecayDays
    ]
  }
}];

const state = $('Build Memory Search Query').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.id);

const memories = rows.map(r => ({
  id: r.id,
  content: r.content,
  type: r.memory_type,
  importance: Number(r.importance),
  similarity: Number(Number(r.similarity).toFixed(3)),
  score: Number(Number(r.score).toFixed(3)),
  createdAt: r.created_at
}));

const memoryBlock = memories
  .map(m => '- [' + m.type + ', saved ' + String(m.createdAt).slice(0, 10) + '] ' + m.content)
  .join('\n') || 'No relevant long-term memories yet.';

return [{
  json: {
    ...state,
    memories,
    memoryBlock,
    memoryIdsLiteral: '{' + memories.map(m => m.id).join(',') + '}'
  }
}];

