const s = $input.first().json;

const turns = (s.history || []).slice(-(s.shortTermMaxTurns * 2)).map(m => ({ role: m.role, content: m.content }));
const messages = [...turns, { role: 'user', content: s.message }];
while (messages.length > 1 && messages[0].role !== 'user') messages.shift();

const system = [
  'You are a helpful assistant with persistent memory of this user across conversations.',
  'Use the long-term memories below when they are relevant, naturally and without listing them or mentioning a database. If a memory conflicts with what the user just said, trust the user and the newer information. If you are unsure whether a remembered detail still applies, ask. Never invent memories.',
  'Long-term memories about the user:\n' + s.memoryBlock
].join('\n\n');

return [{ json: { ...s, replyRequest: { model: s.chatModel, max_tokens: 1200, system, messages } } }];

const s = $('Build Reply Request').first().json;
const r = $input.first().json;
const { replyRequest, ...rest } = s;

const text = Array.isArray(r.content)
  ? r.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim()
  : '';
const replyFailed = !text;
const reply = replyFailed ? 'Sorry, I could not generate a reply right now. Please try again.' : text;

const maxMsgs = s.shortTermMaxTurns * 2;
const newHistory = replyFailed
  ? s.history
  : [...s.history, { role: 'user', content: s.message }, { role: 'assistant', content: reply }].slice(-maxMsgs);

return [{
  json: {
    ...rest,
    reply,
    replyFailed,
    newHistory,
    webhookResponse: {
      requestId: s.requestId,
      userId: s.userId,
      sessionId: s.sessionId,
      reply,
      memoryContext: {
        retrieved: s.memories.length,
        degraded: s.memorySearchDegraded,
        memories: s.memories.map(m => ({ id: m.id, type: m.type, content: m.content, similarity: m.similarity }))
      },
      durationMs: Date.now() - new Date(s.startedAt).getTime()
    }
  }
}];

const s = $input.first().json;
if (s.replyFailed) return [];

const shape = JSON.stringify({
  memories: [{ content: 'short self-contained statement about the user', type: 'fact | preference | goal | event | relationship', importance: 0.5 }]
});

const system = [
  'You maintain the long-term memory of an AI assistant. From the latest exchange, extract only durable, useful information about the user: stable facts, preferences, goals, decisions, relationships and important events.',
  'Ignore small talk, one-off questions, and anything the assistant said that the user did not confirm. Never store sensitive data such as passwords, payment details or government IDs. Do not repeat anything already in the known memories.',
  'Write each memory as a short third-person statement, for example: The user prefers TypeScript over JavaScript. Set importance from 0 to 1 (1 = critical to remember). Return an empty list if nothing is worth keeping.',
  'Respond ONLY with valid JSON, no prose, matching exactly this shape: ' + shape
].join('\n\n');

const recent = (s.history || []).slice(-6).map(m => m.role + ': ' + m.content.slice(0, 500)).join('\n') || 'None';
const user = 'Known memories:\n' + s.memoryBlock
  + '\n\nRecent conversation:\n' + recent
  + '\n\nLatest exchange:\nuser: ' + s.message + '\nassistant: ' + s.reply;

return [{ json: { ...s, extractionRequest: { model: s.extractionModel, max_tokens: 800, system, messages: [{ role: 'user', content: user }] } } }];

const s = $('Build Memory Extraction Request').first().json;
const r = $input.first().json;

let list = [];
try {
  const raw = Array.isArray(r.content) ? r.content.filter(b => b.type === 'text').map(b => b.text).join('') : '{}';
  const parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
  list = Array.isArray(parsed.memories) ? parsed.memories : [];
} catch (e) { list = []; }

const TYPES = ['fact', 'preference', 'goal', 'event', 'relationship'];
const seen = new Set();
const newMemories = [];
for (const m of list) {
  if (!m) continue;
  const content = String(m.content || '').trim();
  const key = content.toLowerCase();
  let importance = Number(m.importance);
  if (!Number.isFinite(importance)) importance = 0.5;
  importance = Math.min(1, Math.max(0, importance));
  if (content.length < 5 || content.length > 500) continue;
  if (importance < s.minImportanceToStore || seen.has(key)) continue;
  seen.add(key);
  newMemories.push({ content, type: TYPES.includes(m.type) ? m.type : 'fact', importance });
  if (newMemories.length >= s.maxMemoriesPerTurn) break;
}

return [{ json: { ...s, newMemories, hasNewMemories: newMemories.length > 0 } }];

const s = $('Parse Extracted Memories').first().json;
const r = $input.first().json;

const data = (Array.isArray(r.data) ? r.data : []).slice().sort((a, b) => (a.index || 0) - (b.index || 0));
const dim = Number(s.embeddingDimensions) || 1024;

const out = [];
s.newMemories.forEach((m, i) => {
  const emb = data[i] && data[i].embedding;
  if (!Array.isArray(emb) || emb.length !== dim) return; // skip anything we could not embed correctly
  out.push({
    json: {
      upsertParams: [s.userId, m.content, '[' + emb.join(',') + ']', m.type, m.importance, s.dedupeSimilarityThreshold, s.sessionId]
    }
  });
});

return out;

const raw = $input.first().json;
const p = raw.body || raw;

const ID_RE = /^[A-Za-z0-9_.@-]{1,128}$/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const userId = String(p.userId || '').trim();
const sessionId = String(p.sessionId || 'default').trim();
const memoryId = p.memoryId ? String(p.memoryId).trim() : null;
const confirmDeleteAll = p.confirmDeleteAll === true;

let error = null;
if (!ID_RE.test(userId)) error = 'userId is required (letters, numbers, . _ @ - only, max 128 chars)';
else if (!ID_RE.test(sessionId)) error = 'sessionId may only contain letters, numbers, . _ @ - (max 128 chars)';
else if (memoryId && !UUID_RE.test(memoryId)) error = 'memoryId must be a UUID';
else if (!memoryId && !confirmDeleteAll) error = 'Provide a memoryId, or set confirmDeleteAll to true to delete all memories for this user';

return [{
  json: {
    forgetValid: !error,
    validationError: error,
    userId,
    memoryId,
    sessionKey: 'session:' + userId + ':' + sessionId
  }
}];
